proc version*(): string =
  ## The library version, e.g. "0.2.18".
  $c_rlx_version()

proc devices*(): seq[string] =
  ## Backends compiled in and usable on this machine.
  var o0: pointer
  check c_rlx_devices(addr o0)
  to(parseJson(takeString(o0)), seq[string])

proc isAvailable*(name: string): bool =
  ## Whether a backend is compiled in and has hardware.
  c_rlx_is_available(cstring(name))

proc parseDevice*(name: string): string =
  ## The canonical label of a device name; errors on an unknown one.
  var o0: pointer
  check c_rlx_parse_device(cstring(name), addr o0)
  takeString(o0)

proc backendsManifest*(): JsonNode =
  ## Every backend rlx knows, with whether this build and machine have it.
  var o0: pointer
  check c_rlx_backends_manifest(addr o0)
  parseJson(takeString(o0))

proc fastestDeviceFor*(graph: Graph; policy: JsonNode = nil): string =
  ## The fastest device that runs every op of `graph`.
  var k: Keep
  var o0: pointer
  check c_rlx_fastest_device_for(graph.h, k.json(policy), addr o0)
  takeString(o0)

proc deviceReport*(graph: Graph; policy: JsonNode = nil): JsonNode =
  ## Every device's verdict on `graph`: available, supports it, why not.
  var k: Keep
  var o0: pointer
  check c_rlx_device_report(graph.h, k.json(policy), addr o0)
  parseJson(takeString(o0))

proc check*(graph: Graph; options: JsonNode = nil): JsonNode =
  ## Static analysis of `graph` across backends: unsupported ops, numerics, cost.
  var k: Keep
  var o0: pointer
  check c_rlx_check(graph.h, k.json(options), addr o0)
  parseJson(takeString(o0))

proc checkBackends*(): seq[string] =
  ## The backends `check` can analyse.
  var o0: pointer
  check c_rlx_check_backends(addr o0)
  to(parseJson(takeString(o0)), seq[string])

proc grad*(graph: Graph; wrt: openArray[int]): Graph =
  ## A graph whose outputs are [loss, …d(loss)/d(wrt)], with a `d_output` seed input.
  var k: Keep
  var o0: pointer
  check c_rlx_grad(graph.h, k.u32s(wrt), csize_t(wrt.len), addr o0)
  adopt(Graph, o0)

proc jvp*(graph: Graph; tangentFor: openArray[int]): Graph =
  ## Forward mode: [...primals, ...tangents], one `tangent_<name>` input per seeded node.
  var k: Keep
  var o0: pointer
  check c_rlx_jvp(graph.h, k.u32s(tangentFor), csize_t(tangentFor.len), addr o0)
  adopt(Graph, o0)

proc hvp*(graph: Graph; wrt: openArray[int]): Graph =
  ## Hessian-vector product, forward-over-reverse.
  var k: Keep
  var o0: pointer
  check c_rlx_hvp(graph.h, k.u32s(wrt), csize_t(wrt.len), addr o0)
  adopt(Graph, o0)

proc vmap*(graph: Graph; names: openArray[string]; batchSize: int): Graph =
  ## Batch the named inputs along a new leading axis.
  var k: Keep
  var o0: pointer
  check c_rlx_vmap(graph.h, k.strs(names), csize_t(names.len), csize_t(batchSize), addr o0)
  adopt(Graph, o0)

proc nthOrderGrad*(graph: Graph; wrt: string; order: int): Graph =
  ## The order-th derivative of a scalar function w.r.t. scalar input `wrt`.
  var o0: pointer
  check c_rlx_nth_order_grad(graph.h, cstring(wrt), csize_t(order), addr o0)
  adopt(Graph, o0)

proc directionalNthGrad*(graph: Graph; wrt: string; order: int): Graph =
  ## The order-th derivative contracted against one direction per level (`dir_0`, …).
  var o0: pointer
  check c_rlx_directional_nth_grad(graph.h, cstring(wrt), csize_t(order), addr o0)
  adopt(Graph, o0)

proc exportFpga*(graph: Graph; outDir: string; options: JsonNode = nil): seq[string] =
  ## Export an INT8 (or legalizable f32) graph as SystemVerilog under `out_dir`; returns the files written.
  var k: Keep
  var o0: pointer
  check c_rlx_export_fpga(graph.h, cstring(outDir), k.json(options), addr o0)
  to(parseJson(takeString(o0)), seq[string])

proc newGraph*(name: string = "graph"): Graph =
  var o0: pointer
  check c_rlx_graph_new(cstring(name), addr o0)
  adopt(Graph, o0)

proc clone*(self: Graph): Graph =
  ## A deep copy — compile one, keep building on the other.
  var o0: pointer
  check c_rlx_graph_clone(self.h, addr o0)
  adopt(Graph, o0)

proc isConsumed*(self: Graph): bool =
  ## Whether a compile (or a body-graph argument) consumed it.
  c_rlx_graph_is_consumed(self.h)

proc splice*(target: Graph; source: Graph; options: JsonNode = nil): seq[int] =
  ## Copy `source` into `target` (both borrowed; `target` grows) and return
  ## `source`'s outputs as `target` nodes. options: {bind: {leaf name: node},
  ## prefix, adapt_shapes}. Unbound same-named leaves are shared (a tied weight)
  ## unless `prefix` keeps them apart. On error `target` is unchanged.
  var k: Keep
  var o0: RlxSlice
  check c_rlx_splice(target.h, source.h, k.json(options), addr o0)
  takeU32s(o0)

proc parallel*(a: Graph; b: Graph; name: Option[string] = none(string)): Graph =
  ## `a` and `b` side by side: a's outputs, then b's; same-named leaves shared.
  var o0: pointer
  check c_rlx_parallel(a.h, b.h, optStr(name), addr o0)
  adopt(Graph, o0)

proc sequential*(a: Graph; b: Graph; name: Option[string] = none(string)): Graph =
  ## `b` after `a`: b's inputs, in creation order, are fed by a's outputs.
  var o0: pointer
  check c_rlx_sequential(a.h, b.h, optStr(name), addr o0)
  adopt(Graph, o0)

proc extract*(graph: Graph; outputs: openArray[int]): Graph =
  ## The subgraph computing `outputs`, with them as its outputs.
  var k: Keep
  var o0: pointer
  check c_rlx_extract(graph.h, k.u32s(outputs), csize_t(outputs.len), addr o0)
  adopt(Graph, o0)

proc newPartition*(graph: Graph; assign: openArray[int]): Partition =
  ## Node i goes to part assign[i] (`node_count()` entries; inputs', params'
  ## and constants' are ignored). Every edge must run to the same or a later part.
  var k: Keep
  var o0: pointer
  check c_rlx_partition_new(graph.h, k.u32s(assign), csize_t(assign.len), addr o0)
  adopt(Partition, o0)

proc splitAt*(_: typedesc[Partition]; graph: Graph; cut: openArray[int]): Partition =
  ## Two parts: `cut` and everything it reads, then the rest.
  var k: Keep
  var o0: pointer
  check c_rlx_partition_split_at(graph.h, k.u32s(cut), csize_t(cut.len), addr o0)
  adopt(Partition, o0)

proc components*(_: typedesc[Partition]; graph: Graph): Partition =
  ## One part per independent subgraph; the parts import nothing.
  var o0: pointer
  check c_rlx_partition_components(graph.h, addr o0)
  adopt(Partition, o0)

proc numParts*(self: Partition): int =
  ## The number of parts.
  var o0: csize_t
  check c_rlx_partition_num_parts(self.h, addr o0)
  int(o0)

proc graph*(self: Partition; part: int): Graph =
  ## A copy of one part's graph.
  var o0: pointer
  check c_rlx_partition_graph(self.h, csize_t(part), addr o0)
  adopt(Graph, o0)

